import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.BXzK3EA4.js";const i="/img/AI/%E5%AD%A6%E4%B9%A0%E8%AE%A1%E5%88%92/stages.svg",u=JSON.parse('{"title":"学习阶段","description":"Python → LLM API → FastAPI。","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/12-学习阶段.md","filePath":"agent/学习计划/12-学习阶段.md","lastUpdated":1793203221000}'),r={name:"agent/学习计划/12-学习阶段.md"};function n(s,a,c,d,p,h){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="学习阶段" tabindex="-1">学习阶段 <a class="header-anchor" href="#学习阶段" aria-label="Permalink to &quot;学习阶段&quot;">​</a></h1><p><img src="'+i+'" alt="AI 开发四阶段:按依赖顺序推进,每一阶段都能独立跑通再进下一步"></p><h2 id="第一阶段-先把「能调通」打通" tabindex="-1">第一阶段:先把「能调通」打通 <a class="header-anchor" href="#第一阶段-先把「能调通」打通" aria-label="Permalink to &quot;第一阶段:先把「能调通」打通&quot;">​</a></h2><p>Python → LLM API → FastAPI。</p><ul><li>用 uv 建好虚拟环境,装好依赖</li><li>跑通第一个 <code>/chat/completions</code> 调用,搞清楚 token 用量</li><li>用 FastAPI 包一层 HTTP 接口,能被别人调用</li></ul><h2 id="第二阶段-再做「能检索」" tabindex="-1">第二阶段:再做「能检索」 <a class="header-anchor" href="#第二阶段-再做「能检索」" aria-label="Permalink to &quot;第二阶段:再做「能检索」&quot;">​</a></h2><p>RAG → Embedding → pgvector。</p><ul><li>文档加载与分块,确定 chunk 大小与重叠</li><li>算 Embedding 写入 pgvector,建好索引</li><li>检索 top-k 拼进 Prompt,先做个能用的知识库问答</li></ul><h2 id="第三阶段-然后做「能行动」" tabindex="-1">第三阶段:然后做「能行动」 <a class="header-anchor" href="#第三阶段-然后做「能行动」" aria-label="Permalink to &quot;第三阶段:然后做「能行动」&quot;">​</a></h2><p>Agent → Tool Calling → MCP。</p><ul><li>让模型自己决定调用哪个工具、传什么参数</li><li>用 MCP 统一工具接入方式,加新工具不用改 Agent</li><li>工具结果回传后继续推理,直到拿到答案</li></ul><h2 id="最后-把本地模型也接进来" tabindex="-1">最后:把本地模型也接进来 <a class="header-anchor" href="#最后-把本地模型也接进来" aria-label="Permalink to &quot;最后:把本地模型也接进来&quot;">​</a></h2><p>Ollama。</p><p>主流程仍然走 API,只在敏感场景或离线时切到本地模型,顺带把成本压下来。</p><blockquote><p>不要跳阶段:RAG 之前如果 API 调不通,后面每一层都会卡在同一个地方。</p></blockquote>',15)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
